SET FOREIGN_KEY_CHECKS=0;

-- ----------------------------
-- Table structure for `mob_spawn_points`
-- ----------------------------
DROP TABLE IF EXISTS `mob_spawn_points`;
CREATE TABLE `mob_spawn_points` (
  `mobid` int(10) NOT NULL,
  `spawnslotid` tinyint(3)  NOT NULL DEFAULT 0,
  `mobname` varchar(24) DEFAULT NULL,
  `polutils_name` varchar(50) DEFAULT NULL,
  `groupid` int(10) unsigned NOT NULL DEFAULT '0',
  `minLevel` tinyint(2) unsigned NOT NULL DEFAULT '0',
  `maxLevel` tinyint(2) unsigned NOT NULL DEFAULT '0',
  `pos_x` float(7,3) NOT NULL DEFAULT '0',
  `pos_y` float(7,3) NOT NULL DEFAULT '0',
  `pos_z` float(7,3) NOT NULL DEFAULT '0',
  `pos_rot` tinyint(3) unsigned NOT NULL DEFAULT '0',
  `spawnHour` tinyint(3) unsigned DEFAULT NULL,
  `despawnHour` tinyint(3) unsigned DEFAULT NULL,
  PRIMARY KEY (`mobid`)
) ENGINE=Aria TRANSACTIONAL=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci AVG_ROW_LENGTH=33;

